/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* Designme shared core: tokens for Blueprint (default), Soft (data-style="soft") and Clean (data-style="clean"), on <html> or on any element around the components, light and dark (<html data-theme="dark">) */
:where([data-c]) [hidden]{display:none!important}
/* hold(): an end state centred in the height its component had */
.held{display:flex;flex-direction:column;justify-content:center}
/* the glide starts fast in both styles, so the field is on its way up before an opening list reaches the stage's edge */
.glide{transform:translateY(var(--dm-gy,0px));transition:transform var(--dm-t) cubic-bezier(.22,1,.36,1)}
/* and a list that opens under a gliding field fades in a beat after it starts to move */
.glide>.csx-pop.open{transition-delay:.08s}
.glide>.msc-pop.open{transition-delay:.08s,.08s,.08s,0s}
.glide>.six-pop.open{transition-delay:.08s}
/* Soft 2: one quiet surface per object, grey type for finished work, motion only on what is happening now */
:root,[data-style="soft"],[data-style="clean"]{
  --dm-motion:soft;
  --dm-page:#f7f7f7; --dm-stage:#fafafa; --dm-surface:#ffffff; --dm-raised:#ffffff;
  --dm-fg:#171717; --dm-fg2:#525252; --dm-muted:#6a6a6a; --dm-faint:#c4c4c4; --dm-rail:#d4d4d4; --dm-line:#e8e8e8; --dm-field-line:#d4d4d4; --dm-line-strong:#858585; --dm-field-line-strong:#b3b3b3;
  --dm-chip:#f3f3f3; --dm-hover:#ebebeb; --dm-press:#e3e3e3; --dm-wash:#f9f9f9; --dm-row:#fafafa;
  --dm-soft:#ececec; --dm-soft-h:#e3e3e3; --dm-soft-ring:inset 0 0 0 1px rgba(0,0,0,.03); --dm-dis:#a6a6a6;
  /* disabled: text and icons take --dm-dis; a control with a fill swaps it for --dm-dis-fill (Blueprint hatches it) */
  --dm-dis-fill:var(--dm-soft); --dm-dis-hatch:none;
  --dm-shadow-lift:0 0 0 1px rgba(0,0,0,.05),0 2px 4px rgba(0,0,0,.04),0 16px 32px -10px rgba(0,0,0,.16);
  /* the accent has three roles: --dm-accent fills (with --dm-on-accent on top, 4.5:1), --dm-accent-fg is text and icons in the accent
     (4.5:1 on the surface, and on the chips and tints it sits on) and --dm-accent-mark is lines, rings and chart marks (3:1). A
     light accent like lime keeps its fills and gets a darker mark and ink-coloured text on a light page */
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#0f5fd5; --dm-accent-mark:#0a66ff; --dm-sel:color-mix(in srgb,var(--dm-accent) 6%,transparent);
  /* fields (text fields, textareas, search fields, dropdown triggers) have a dimmed grey edge, --dm-field-line, that steps up
     a little, to --dm-field-line-strong, while they have the focus. The keyboard's focus ring on every other control is 2px of
     a stronger grey (--dm-line-strong, as --dm-focus), as an outline offset 2px, or as a 2px box-shadow ring where an outline would be clipped. Never
     the accent and never black, and only from the keyboard (:focus-visible), so a click or a tap never shows one */
  --dm-focus:var(--dm-line-strong);
  --dm-ink:#1b1b1b; --dm-on-ink:#ffffff;
  /* the status tints sit with the core tag colours below (21 Nov): a step stronger in light, deep and opaque in dark, each
     keeping its text at 4.5:1 and APCA Lc 60 on every surface */
  --dm-ok:#0c7c39; --dm-ok-bg:#daf8df; --dm-ok-mark:#00a23d; --dm-warn:#9a4704; --dm-warn-bg:#ffe5b8; --dm-warn-mark:#f76700; --dm-bad:#d0111c; --dm-bad-bg:#fee4e1; --dm-bad-mark:#f04438;
  --dm-merge:#7c4cd4; --dm-merge-bg:#f2ecfd; --dm-add:#187633; --dm-del:#c7212c;
  /* the core tag colours (owner, 21 Nov: "make it more saturated... look at the Attio chips"): a clearly coloured tint and the
     most saturated text of its hue that keeps 4.5:1 and APCA Lc 60 on it (and on every light surface) */
  --dm-pb:#0963da; --dm-pb-bg:#e0ecfe; --dm-pl:#7314fa; --dm-pl-bg:#eae8fe; --dm-pm:#0c7a38; --dm-pm-bg:#d5f5da; --dm-pp:#ab4d0a; --dm-pp-bg:#fee6d3;
  --dm-pr:#ce1141; --dm-pr-bg:#fee4e4; --dm-py:#8c610a; --dm-py-bg:#f7ebc6; --dm-pk:#c6107e; --dm-pk-bg:#fee3ed; --dm-pt:#0c7679; --dm-pt-bg:#c5f6fb;
  /* avatars have colours of their own, the same in every style and theme: a bright fill and the initials' ink on it (4.5:1,
     APCA Lc 60). Blue, violet, red and pink are deep enough for white; green, teal, yellow and orange are too light for white
     and take a dark ink of their own hue. An avatar given one of these, var(--dm-av-l), takes its ink, var(--dm-av-l-ink), on its own */
  --dm-av-b:#126fe6; --dm-av-b-ink:#ffffff; --dm-av-l:#834ff5; --dm-av-l-ink:#ffffff; --dm-av-r:#d73341; --dm-av-r-ink:#ffffff; --dm-av-k:#cf3288; --dm-av-k-ink:#ffffff;
  --dm-av-m:#27cf86; --dm-av-m-ink:#052616; --dm-av-t:#28c9d8; --dm-av-t-ink:#042428; --dm-av-y:#e9ac1a; --dm-av-y-ink:#2a1d03; --dm-av-p:#fda154; --dm-av-p-ink:#301804;
  --dm-ts:#2c6cb2; --dm-react:#0a738b;
  /* every raised surface carries its own hairline edge, so nothing needs a separate ring */
  /* soft, layered shadows: a hairline, a contact shadow and two wide, faint ones. No highlight on the top edge or glow inside
     (owner, 18 Nov): Soft's cards and buttons are lit from outside only */
  --dm-shadow:0 0 0 1px rgba(0,0,0,.03),0 1px 1px rgba(0,0,0,.025),0 2px 4px -1px rgba(0,0,0,.03),0 8px 16px -6px rgba(0,0,0,.05),0 20px 36px -14px rgba(0,0,0,.08);
  --dm-shadow-pop:0 0 0 1px rgba(0,0,0,.035),0 1px 2px rgba(0,0,0,.03),0 4px 10px -4px rgba(0,0,0,.05),0 14px 28px -10px rgba(0,0,0,.08),0 32px 56px -24px rgba(0,0,0,.12);
  /* a white button on a tinted row or notice: a hairline edge and no shadow (owner, 18 Nov: Soft's buttons cast none) */
  --dm-on-tint-btn:inset 0 0 0 1px rgba(0,0,0,.08); --dm-on-tint-btn-h:inset 0 0 0 1px rgba(0,0,0,.14); --dm-tint-h:color-mix(in srgb,currentColor 6%,transparent);
  --dm-shadow-toast:0 0 0 1px rgba(0,0,0,.03),0 4px 12px rgba(0,0,0,.08);
  --dm-hl:#fdeb9a; --dm-hl-ok:#d3f1df;
  /* Soft is plush: every corner is scaled by --dm-rk, and larger still where the browser draws true squircles (below) */
  --dm-rk:1.25;
  --dm-r-card:calc(16px * var(--dm-rk-l,var(--dm-rk)));
  /* spacing runs on a 4px scale, and corners on a small set of radii; values off the scale are still written out */
  --dm-s-1:4px; --dm-s-2:8px; --dm-s-3:12px; --dm-s-4:16px; --dm-s-5:20px; --dm-s-6:24px; --dm-s-8:32px; --dm-r-xs:calc(4px * var(--dm-rk-s,var(--dm-rk))); --dm-r-lg:calc(20px * var(--dm-rk-l,var(--dm-rk))); --dm-r-in:calc(12px * var(--dm-rk-l,var(--dm-rk))); --dm-r-sm:calc(8px * var(--dm-rk-m,var(--dm-rk))); --dm-r-pill:999px;
  /* fields and tags have slightly rounded corners, never pills: --dm-r-field for one-line fields and dropdown triggers, --dm-r-box
     for boxes you write several lines in, --dm-r-tag for tags. Where the browser smooths corners (corner-shape: squircle) a
     corner looks smaller, so each takes the larger -sq radius there to look the same size. Fields share one height and,
     where a component is a single field, one width */
  --dm-r-field:10px; --dm-r-field-sq:16px; --dm-r-box:14px; --dm-r-box-sq:22px; --dm-r-tag:7px; --dm-r-tag-sq:12px;
  --dm-field-h:40px; --dm-field-w:320px;
  --dm-sans:"Inter",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --dm-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --dm-ease:cubic-bezier(.22,1,.36,1); --dm-ease-io:cubic-bezier(.65,0,.35,1);
  --dm-t-fast:.22s; --dm-t:.45s; --dm-t-slow:.7s;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root:not([data-theme="light"]) [data-style="clean"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#363636;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#747474; --dm-line-strong:#808080; --dm-field-line-strong:#a3a3a3;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#2f86ff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616; --dm-seg-k-shadow:0 0 0 1px rgba(255,255,255,.06),0 1px 2px rgba(0,0,0,.35); --dm-tip-bg:#3d3d3b; --dm-tip-fg:var(--dm-fg); --dm-tip-ring:0 0 0 1px rgba(255,255,255,.12);
  --dm-ok:#4ade80; --dm-ok-bg:#14391e; --dm-ok-mark:#1fd160; --dm-warn:#ffc247; --dm-warn-bg:rgba(255,184,40,.2); --dm-warn-mark:#ffa940; --dm-bad:#ffaca4; --dm-bad-bg:#4c221f; --dm-bad-mark:#f97066;
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#9ac1fd; --dm-pb-bg:#1b3051; --dm-pl:#c0b6fd; --dm-pl-bg:#302a4f; --dm-pm:#6ad485; --dm-pm-bg:#14391e; --dm-pp:#fdab81; --dm-pp-bg:#472806;
  --dm-pr:#fda8ab; --dm-pr-bg:#4c2124; --dm-py:#f5b23a; --dm-py-bg:#3b2f04; --dm-pk:#fda4cb; --dm-pk-bg:#492134; --dm-pt:#21dce2; --dm-pt-bg:#05373c;
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.045),0 1px 2px rgba(0,0,0,.28),0 6px 14px -6px rgba(0,0,0,.36),0 20px 36px -14px rgba(0,0,0,.45); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.12),0 2px 4px rgba(0,0,0,.3),0 12px 24px -8px rgba(0,0,0,.45),0 32px 56px -20px rgba(0,0,0,.55); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); --dm-on-tint-btn:inset 0 0 0 1px rgba(255,255,255,.1); --dm-on-tint-btn-h:inset 0 0 0 1px rgba(255,255,255,.16); --dm-tint-h:rgba(0,0,0,.1); color-scheme:dark}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"],:root[data-theme="dark"] [data-style="clean"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#363636;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#747474; --dm-line-strong:#808080; --dm-field-line-strong:#a3a3a3;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#2f86ff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616; --dm-seg-k-shadow:0 0 0 1px rgba(255,255,255,.06),0 1px 2px rgba(0,0,0,.35); --dm-tip-bg:#3d3d3b; --dm-tip-fg:var(--dm-fg); --dm-tip-ring:0 0 0 1px rgba(255,255,255,.12);
  --dm-ok:#4ade80; --dm-ok-bg:#14391e; --dm-ok-mark:#1fd160; --dm-warn:#ffc247; --dm-warn-bg:rgba(255,184,40,.2); --dm-warn-mark:#ffa940; --dm-bad:#ffaca4; --dm-bad-bg:#4c221f; --dm-bad-mark:#f97066;
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#9ac1fd; --dm-pb-bg:#1b3051; --dm-pl:#c0b6fd; --dm-pl-bg:#302a4f; --dm-pm:#6ad485; --dm-pm-bg:#14391e; --dm-pp:#fdab81; --dm-pp-bg:#472806;
  --dm-pr:#fda8ab; --dm-pr-bg:#4c2124; --dm-py:#f5b23a; --dm-py-bg:#3b2f04; --dm-pk:#fda4cb; --dm-pk-bg:#492134; --dm-pt:#21dce2; --dm-pt-bg:#05373c;
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.045),0 1px 2px rgba(0,0,0,.28),0 6px 14px -6px rgba(0,0,0,.36),0 20px 36px -14px rgba(0,0,0,.45); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.12),0 2px 4px rgba(0,0,0,.3),0 12px 24px -8px rgba(0,0,0,.45),0 32px 56px -20px rgba(0,0,0,.55); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); --dm-on-tint-btn:inset 0 0 0 1px rgba(255,255,255,.1); --dm-on-tint-btn-h:inset 0 0 0 1px rgba(255,255,255,.16); --dm-tint-h:rgba(0,0,0,.1); color-scheme:dark}

/* the accent's hover fill (--dm-accent-2) and tint (--dm-accent-bg) are worked out from the accent, in every style and theme, so a
   picked accent brings its own. Hovering a filled button moves its fill away from its text colour: darker under white text,
   lighter under dark text, so the label keeps its contrast in every style, theme and accent */
:root,[data-style="soft"],[data-style="clean"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 9%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root:not([data-theme="light"]) [data-style="clean"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"],:root[data-theme="dark"] [data-style="clean"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}
@supports (color:rgb(from red r g b)){:root,[data-style="soft"],[data-style="clean"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root:not([data-theme="light"]) [data-style="clean"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"],:root[data-theme="dark"] [data-style="clean"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,rgb(from var(--dm-on-accent) calc(255 - r) calc(255 - g) calc(255 - b)))}}
@supports not (color:rgb(from red r g b)){:root,[data-style="soft"],[data-style="clean"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root:not([data-theme="light"]) [data-style="clean"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"],:root[data-theme="dark"] [data-style="clean"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000)}:root:not([data-style="soft"],[data-style="clean"]),:root:not([data-style="soft"],[data-style="clean"]):not([data-theme="light"]),:root:not([data-style="soft"],[data-style="clean"])[data-theme="dark"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#fff)}}
/* picked things (chips, options, cards in a picker) are white tiles with a dimmed grey edge, and the picked one's edge
   is a light step stronger, never a dark or black outline */
:root,[data-style="soft"],[data-style="clean"]{--dm-pick-line:var(--dm-rail);--dm-pick-on:var(--dm-faint)}

/* Soft is plush: corners are drawn as squircles where the browser can (corner-shape), and since a squircle's corner
   reads smaller than a round one of the same radius, the radii grow with it. Circles (spinners, loader rings, avatars,
   dots) stay round; pills, chips, buttons and switchers are squircles too. Blueprint stays square (its corners are 0) */
@supports (corner-shape:squircle){
:root,[data-style="soft"],[data-style="clean"]{--dm-rk:1.7}
:root:not([data-style="soft"],[data-style="clean"]){--dm-rk:1}
:where([data-c]) *,:where([data-c]) *::before,:where([data-c]) *::after{corner-shape:squircle}
.acx-n .s,.afx-pen,.afx-r b,.agx-now i,.aln-cw-tr b,.aln-pk,.asx-lp-stop,.asx-lp-th,.asx-lp-th i,.asx-tb-dot,.atx-cmp-ok,.atx-cmp-send,.atx-cmp-x,.av,.bdg-dot,.bdg-x,.bdg-x:focus-visible,.btx-live,.ccx-fl .flag,.ccx-sw,.cmx-go,.cmx-pin,.cpx-att .fchip .rt,.cpx-att .fchip .x,.cpx-dot,.cpx-send,.ctb-n .s,.dot,.ecx-days b,.ecx-dh.t b,.evr-dot,.evr-jg-arc .tr,.evr-jg-arc i,.fxp-n .ag,.ib,.lnx-k i,.lnx-pt,.mix-dot,.msc-c button,.ntx-n .u,.plx-s .n,.pulse,.rxx-add,.sgc-wr .e i,.spin,.ssx-ics span,.stx-conf i.d,.stx-st .n,.think i,.tk-st .mk,.tsk-c .g,.tst-t .g,.ttp-av,.cxm-av,.crs-dots button,.rdx-lg i,.scx-lg i.c,.cvq-lg i.c,.rgx-r i,.wsx-marks span,.ths-dg i,.ths-mtx i,.hsc-dot,.hsc-pt i,.mtx-now i{corner-shape:round}
.aln-det div::before{corner-shape:round}
.asx-lp-rg::-moz-range-thumb{corner-shape:round}
.asx-lp-rg::-webkit-slider-thumb{corner-shape:round}
.btx-live::after{corner-shape:round}
.dpk-d.t::after{corner-shape:round}
.ecx-now::before{corner-shape:round}
.fxp-tree::-webkit-scrollbar-thumb{corner-shape:round}
.hand::before{corner-shape:round}
.hnx-dot{corner-shape:round}
.pulse::after{corner-shape:round}
.radar::after{corner-shape:round}
.radar::before{corner-shape:round}
.sgc-mo .d.e::after{corner-shape:round}
.stx-ok::after{corner-shape:round}
.tmx-body::-webkit-scrollbar-thumb{corner-shape:round}
.toggle::after{corner-shape:round}
.afx-desk::before{corner-shape:round}
}
/* ---------- page shell ---------- */
:where([data-c]) *{box-sizing:border-box}
:where([data-c]) button,:where([data-c]) input,:where([data-c]) textarea,:where([data-c]) select{font:inherit;color:inherit}
:where([data-c]) button{background:none;border:0;padding:0;cursor:pointer}
/* one weight for emphasis: medium, never bold */
:where([data-c]) b,:where([data-c]) strong{font-weight:500}
:where([data-c]) :focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)))}
/* a control pressed with a pointer, or a button that got the focus back after a click (closePops), keeps no ring until a key
   that moves or acts is pressed; a ring drawn on the control's neighbour (a checkbox's box) goes with it */
[data-nofv]:focus-visible,[data-nofv]:focus-visible+*{outline:0}
/* a field shows the focus with its own edge, which steps up to --dm-field-line-strong, so it never takes the ring as well */
:where([data-c]) :focus-visible:is(input:not([type="checkbox"],[type="radio"],[type="range"],[type="file"],[type="button"],[type="submit"],[type="reset"]),textarea,select,[contenteditable]:not([contenteditable="false"])){outline:0}
.stage-in{width:100%;max-width:440px;min-width:0;position:relative;container-type:inline-size}
.card.wide .stage-in{max-width:720px}

/* ---------- icons ---------- */
.i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.i.s{width:14px;height:14px}.i.xs{width:12px;height:12px}.i.l{width:18px;height:18px}
.brand{width:16px;height:16px;display:block;flex:none}
.flag{width:20px;height:15px;border-radius:var(--dm-r-tiny,3px);object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

/* ---------- primitives ---------- */
.mono{font-family:var(--dm-mono)}
.sp{flex:1}
.num{font-variant-numeric:tabular-nums}
.muted{color:var(--dm-muted)}.fg2{color:var(--dm-fg2)}
.panel{background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);position:relative}
.ib{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast),transform .15s}
